function run(resposta) {
    try {
        if (resposta === null || resposta === undefined) {
            return "ALUNO";
        }

        var texto = String(resposta).toLowerCase().trim();

        // Remove acentos
        texto = texto
            .replace(/[áàâãä]/g, "a")
            .replace(/[éèêë]/g, "e")
            .replace(/[íìîï]/g, "i")
            .replace(/[óòôõö]/g, "o")
            .replace(/[úùûü]/g, "u")
            .replace(/ç/g, "c");

        // Identifica o setor
        if (/\bestagio\b/.test(texto)) {
            return "SETOR_ESTAGIO";
        }

        if (/\bcra\b/.test(texto)) {
            return "SETOR_CRA";
        }

        if (/\bbiblioteca\b/.test(texto)) {
            return "SETOR_BIBLIOTECA";
        }

        // Se não for um dos três setores
        return "ALUNO";

    } catch (e) {
        return "ALUNO";
    }
}

function run(retornoIA) {
  try {
    var obj = typeof retornoIA === "string"
      ? JSON.parse(retornoIA)
      : retornoIA;

    var resposta = obj.resposta || "";

    return String(resposta)
      .split("\\n").join("\n")
      .split("\\r").join("")
      .split("\\t").join(" ");
  } catch (e) {
    return String(retornoIA || "")
      .split("\\n").join("\n")
      .split("\\r").join("")
      .split("\\t").join(" ");
  }
}

function run(mensagem) {
    var LIMITE = 2000; // mesmo limite de caracteres da API

    var limpa = (mensagem === null || mensagem === undefined) ? "" : String(mensagem);

    // Quebras de linha, tabs e outros caracteres de controle viram espaço
    limpa = limpa
        .replace(/[\u0000-\u001F\u007F]+/g, " ")
        .replace(/\s+/g, " ")
        .replace(/^\s+|\s+$/g, "");

    if (limpa.length > LIMITE) {
        limpa = limpa.substring(0, LIMITE);
    }

    // JSON.stringify escapa aspas e barras; tira as aspas das pontas porque o corpo já as tem
    var escapada = JSON.stringify(limpa);
    return escapada.substring(1, escapada.length - 1);
}

